# ============================================================ GEOMETRY
def area2(P):
    a = 0.0
    for i in range(len(P)):
        x0, y0 = P[i][0], P[i][1]
        x1, y1 = P[(i + 1) % len(P)][0], P[(i + 1) % len(P)][1]
        a += x0 * y1 - x1 * y0
    return a / 2.0


def ring(P):
    """Open ring (no repeated end point)."""
    P = [(p[0], p[1]) for p in P]
    if len(P) > 1 and abs(P[0][0] - P[-1][0]) < 1e-9 and abs(P[0][1] - P[-1][1]) < 1e-9:
        P = P[:-1]
    return P


def pip(x, y, P):
    ins = False
    j = len(P) - 1
    for i in range(len(P)):
        xi, yi = P[i][0], P[i][1]
        xj, yj = P[j][0], P[j][1]
        if (yi > y) != (yj > y) and x < (xj - xi) * (y - yi) / ((yj - yi) or 1e-12) + xi:
            ins = not ins
        j = i
    return ins


class Rect(object):
    """A plan rectangle with axes a (unit vector) and b = a turned +90 deg: centre, half sizes."""

    def __init__(self, cx, cy, ang, hu, hv):
        self.cx, self.cy, self.ang, self.hu, self.hv = cx, cy, ang, hu, hv
        self.a = (math.cos(ang), math.sin(ang))
        self.b = (-math.sin(ang), math.cos(ang))

    def loc(self, x, y):
        dx, dy = x - self.cx, y - self.cy
        return (dx * self.a[0] + dy * self.a[1], dx * self.b[0] + dy * self.b[1])

    def glob(self, u, v):
        return (self.cx + u * self.a[0] + v * self.b[0], self.cy + u * self.a[1] + v * self.b[1])

    def inside(self, x, y, pad=0.0):
        u, v = self.loc(x, y)
        return abs(u) <= self.hu + pad and abs(v) <= self.hv + pad

    def corners(self):
        return [self.glob(-self.hu, -self.hv), self.glob(self.hu, -self.hv), self.glob(self.hu, self.hv),
                self.glob(-self.hu, self.hv)]

    def clip_poly(self, P):
        """Sutherland-Hodgman against the rectangle."""
        L = [self.loc(p[0], p[1]) for p in P]
        for k, s in ((0, 1), (0, -1), (1, 1), (1, -1)):
            lim = self.hu if k == 0 else self.hv
            if not L:
                break
            out = []
            for i in range(len(L)):
                c, p = L[i], L[i - 1]
                ci, pi_ = s * c[k] <= lim, s * p[k] <= lim
                if ci:
                    if not pi_:
                        out.append(_cut(p, c, k, s * lim))
                    out.append(c)
                elif pi_:
                    out.append(_cut(p, c, k, s * lim))
            L = out
        return [self.glob(u, v) for u, v in L] if len(L) >= 3 else []

    def clip_line(self, P):
        """A polyline cut to the rectangle: a list of polylines."""
        out, cur = [], []
        L = [self.loc(p[0], p[1]) for p in P]
        for i in range(len(L) - 1):
            seg = _clip_seg(L[i], L[i + 1], self.hu, self.hv)
            if seg is None:
                if len(cur) > 1:
                    out.append(cur)
                cur = []
                continue
            a, b = seg
            if cur and abs(cur[-1][0] - a[0]) < 1e-9 and abs(cur[-1][1] - a[1]) < 1e-9:
                cur.append(b)
            else:
                if len(cur) > 1:
                    out.append(cur)
                cur = [a, b]
        if len(cur) > 1:
            out.append(cur)
        return [[self.glob(u, v) for u, v in c] for c in out]


def _cut(p, c, k, lim):
    t = (lim - p[k]) / ((c[k] - p[k]) or 1e-12)
    return (p[0] + t * (c[0] - p[0]), p[1] + t * (c[1] - p[1]))


def _clip_seg(p, q, hu, hv):
    t0, t1 = 0.0, 1.0
    dx, dy = q[0] - p[0], q[1] - p[1]
    for pp, qq in ((-dx, p[0] + hu), (dx, hu - p[0]), (-dy, p[1] + hv), (dy, hv - p[1])):
        if abs(pp) < 1e-12:
            if qq < 0:
                return None
            continue
        r = qq / pp
        if pp < 0:
            t0 = max(t0, r)
        else:
            t1 = min(t1, r)
        if t0 > t1:
            return None
    return ((p[0] + t0 * dx, p[1] + t0 * dy), (p[0] + t1 * dx, p[1] + t1 * dy))


def min_rect(P, ang):
    """The smallest rectangle with axis angle ang holding the points P."""
    c, s = math.cos(ang), math.sin(ang)
    us = [x * c + y * s for x, y in P]
    vs = [-x * s + y * c for x, y in P]
    u0, u1, v0, v1 = min(us), max(us), min(vs), max(vs)
    uc, vc = (u0 + u1) / 2, (v0 + v1) / 2
    return Rect(uc * c - vc * s, uc * s + vc * c, ang, (u1 - u0) / 2, (v1 - v0) / 2)


def seg_dist(px, py, a, b):
    dx, dy = b[0] - a[0], b[1] - a[1]
    L2 = dx * dx + dy * dy
    t = 0.0 if L2 == 0 else max(0.0, min(1.0, ((px - a[0]) * dx + (py - a[1]) * dy) / L2))
    return math.hypot(px - a[0] - t * dx, py - a[1] - t * dy)


def nice(x):
    """A round number (1, 2, 5 x 10^n) not above x."""
    e = 10 ** math.floor(math.log10(x))
    for m in (5, 2, 1):
        if m * e <= x:
            return m * e
    return e


def fmt_int(n):
    return "{:,}".format(int(round(n)))


# ============================================================ THE VIEW (parallel axonometric)
class View(object):
    """u = x sin t - y cos t; v = (x cos t + y sin t) sin p + z cos p; depth = (x cos t + y sin t) cos p - z sin p
    (the study's projection, corrected 17 Oct). Then u, v to page mm: X = ox + k u, Y = oy + k v."""

    def __init__(self, theta, phi=PHI):
        self.theta, self.phi = theta, phi
        t, p = math.radians(theta), math.radians(phi)
        self.ct, self.st, self.cp, self.sp = math.cos(t), math.sin(t), math.cos(p), math.sin(p)
        self.k, self.ox, self.oy = 1.0, 0.0, 0.0
        self.zg = None                                     # v33: ground height above the extent's lowest point

    def uv(self, x, y, z=0.0):
        w = x * self.ct + y * self.st
        return (x * self.st - y * self.ct, w * self.sp + z * self.cp)

    def depth(self, x, y, z=0.0):
        return (x * self.ct + y * self.st) * self.cp - z * self.sp

    def P(self, x, y, z=0.0):
        if self.zg is not None:                            # v33: everything stands on the survey terrain
            z += self.zg(x, y)
        u, v = self.uv(x, y, z)
        return (self.ox + self.k * u, self.oy + self.k * v)

    def vec(self, dx, dy, dz=0.0):
        """Page mm of a ground (or vertical) vector."""
        w = dx * self.ct + dy * self.st
        return (self.k * (dx * self.st - dy * self.ct), self.k * (w * self.sp + dz * self.cp))

    def facing(self, nx, ny):
        """A wall whose outward normal is (nx, ny): visible, and lit (light from the left of the page)?"""
        vis = nx * self.ct + ny * self.st < -1e-9
        lit = (nx * self.st - ny * self.ct) < 0
        return vis, lit


# ============================================================ PAGE (vector items in mm, y up)
class Page(object):
    def __init__(self, pid, title):
        self.pid, self.title, self.items = pid, title, []

    def poly(self, rings, fill=None, stroke=None, lw=0.1, dash=None, layer="drawing", join=1, stripes=None, alpha=None):
        """alpha: opacity 0-1 of fill and stroke (PDF only, in steps of 0.05; None = opaque)."""
        rings = [r for r in rings if len(r) >= 3]
        if rings:
            self.items.append(("poly", rings, fill, stroke, lw, dash, layer, join, stripes, alpha))

    def line(self, pts, stroke, lw=0.1, dash=None, layer="drawing", cap=1):
        if len(pts) >= 2:
            self.items.append(("line", pts, stroke, lw, dash, layer, cap))

    def circle(self, cx, cy, r, fill=None, stroke=None, lw=0.1, layer="drawing"):
        self.items.append(("circle", cx, cy, r, fill, stroke, lw, layer))

    def text(self, s, x, y, size, color, bold=False, align="L", layer="text", mat=None, halo=None):
        """size = em in mm; align L, C or R on the baseline; mat = 2 x 2 text matrix (columns: text x and y axes per
        mm of em) for words lying in a drawing plane."""
        if s:
            self.items.append(("text", s, x, y, size, color, bold, align, layer, mat, halo))


def hex_rgb(h):
    h = h.lstrip("#")
    return (int(h[0:2], 16) / 255.0, int(h[2:4], 16) / 255.0, int(h[4:6], 16) / 255.0)


# ============================================================ PDF WRITER (no libraries)
_ENC_EXTRA = {u"Ğ": 0x81, u"ğ": 0x8D, u"İ": 0x8F, u"ı": 0x90, u"Ş": 0x9D, u"ş": 0x9E}
_DIFF = "/Differences [129 /Gbreve 141 /gbreve 143 /Idotaccent 144 /dotlessi 157 /Scedilla 158 /scedilla]"


def pdf_str(s):
    out = bytearray()
    for ch in s:
        if ch in _ENC_EXTRA:
            out.append(_ENC_EXTRA[ch])
            continue
        try:
            b = ch.encode("cp1252")
        except Exception:
            b = b"?"
        if b in (b"\x9e",):                      # z caron's slot is used for s cedilla
            b = b"?"
        out += b
    s2 = bytes(out).replace(b"\\", b"\\\\").replace(b"(", b"\\(").replace(b")", b"\\)")
    return b"(" + s2 + b")"


def _f(v):
    s = "{:.3f}".format(v).rstrip("0").rstrip(".")
    return "0" if s in ("-0", "") else s


def page_stream(pg):
    o = []
    A = o.append
    A("2.834646 0 0 2.834646 0 0 cm 1 J 1 j")
    cur = {}

    def col(c, stroke):
        k = "S" if stroke else "f"
        if cur.get(k) == c:
            return
        cur[k] = c
        r, g, b = hex_rgb(c)
        A("{} {} {} {}".format(_f(r), _f(g), _f(b), "RG" if stroke else "rg"))

    def path(pts, close):
        A("{} {} m".format(_f(pts[0][0]), _f(pts[0][1])))
        for p in pts[1:]:
            A("{} {} l".format(_f(p[0]), _f(p[1])))
        if close:
            A("h")

    def lw_dash(lw, dash, cap=1, join=1):
        A("{} w {} J {} j [{}] 0 d".format(_f(lw), cap, join, " ".join(_f(d) for d in (dash or []))))

    for it in pg.items:
        kind = it[0]
        if kind == "poly":
            _, rings, fill, stroke, lw, dash, layer, join, stripes = it[:9]
            alpha = it[9] if len(it) > 9 else None
            if alpha is not None and alpha < 0.975:                 # see-through: an ExtGState of write_pdf
                A("q /A{:02d} gs".format(max(1, int(round(alpha * 20)))))
                cur.clear()
            if fill:
                col(fill, False)
            if stroke:
                col(stroke, True)
                lw_dash(lw, dash, 1, join)
            for r in rings:
                path(r, True)
            A("B*" if fill and stroke else ("f*" if fill else "S"))
            if stripes:                                             # (colour, spacing mm, width mm)
                sc_, sp_, w_ = stripes
                A("q")
                for r in rings:
                    path(r, True)
                A("W* n")
                col(sc_, True)
                lw_dash(w_, None, 0)
                xs = [p[0] for r in rings for p in r]
                ys = [p[1] for r in rings for p in r]
                x0, x1, y0, y1 = min(xs), max(xs), min(ys), max(ys)
                d = x0 - (y1 - y0)
                while d < x1:
                    A("{} {} m {} {} l".format(_f(d), _f(y0), _f(d + (y1 - y0)), _f(y1)))
                    d += sp_
                A("S Q")
                cur.pop("S", None)
            if alpha is not None and alpha < 0.975:
                A("Q")
                cur.clear()
        elif kind == "line":
            _, pts, stroke, lw, dash, layer, cap = it
            col(stroke, True)
            lw_dash(lw, dash, cap)
            path(pts, False)
            A("S")
        elif kind == "circle":
            _, cx, cy, r, fill, stroke, lw, layer = it
            kk = 0.5523 * r
            if fill:
                col(fill, False)
            if stroke:
                col(stroke, True)
                lw_dash(lw, None)
            A("{} {} m".format(_f(cx + r), _f(cy)))
            for (a1, a2, a3) in (((cx + r, cy + kk), (cx + kk, cy + r), (cx, cy + r)),
                                 ((cx - kk, cy + r), (cx - r, cy + kk), (cx - r, cy)),
                                 ((cx - r, cy - kk), (cx - kk, cy - r), (cx, cy - r)),
                                 ((cx + kk, cy - r), (cx + r, cy - kk), (cx + r, cy))):
                A("{} {} {} {} {} {} c".format(_f(a1[0]), _f(a1[1]), _f(a2[0]), _f(a2[1]), _f(a3[0]), _f(a3[1])))
            A("h " + ("B" if fill and stroke else ("f" if fill else "S")))
        elif kind == "text":
            _, s, x, y, size, color, bold, align, layer, mat, halo = it
            w = text_w(s, size, bold)
            reps = [(halo, True), (color, False)] if halo else [(color, False)]
            for c_, hal in reps:
                if hal:
                    r_, g_, b_ = hex_rgb(c_)
                    A("q {} {} {} RG {} w 1 j 1 Tr".format(_f(r_), _f(g_), _f(b_), _f(size * 0.16)))
                else:
                    col(color, False)
                    A("0 Tr")
                _text_ops(A, s, x, y, size, bold, align, mat, w)
                if hal:
                    A("Q")
    return "\n".join(o).encode("latin-1")


def _text_ops(A, s, x, y, size, bold, align, mat, w):
    if mat is None:
        dx = {"L": 0.0, "C": -w / 2, "R": -w}[align]
        A("BT /F{} {} Tf 1 0 0 1 {} {} Tm".format(2 if bold else 1, _f(size), _f(x + dx), _f(y)))
    else:
        (a, b), (c, d) = mat
        f = {"L": 0.0, "C": -w / 2 / size, "R": -w / size}[align]
        A("BT /F{} 1 Tf {} {} {} {} {} {} Tm".format(2 if bold else 1, _f(a * size), _f(b * size), _f(c * size),
                                                    _f(d * size), _f(x + f * a * size), _f(y + f * b * size)))
    A(pdf_str(s).decode("latin-1") + " Tj ET")


def write_pdf(pages, path):
    objs = []

    def add(b):
        objs.append(b)
        return len(objs)
    font = pdf_fonts(add, ("R", "B"))                     # G2/G3 28 Oct: Arial embedded (the board's pdf_fonts)
    gs = [add("<< /Type /ExtGState /ca {0} /CA {0} >>".format(_f(i / 20.0)).encode("latin-1")) for i in range(1, 20)]
    gs_res = " ".join("/A{:02d} {} 0 R".format(i + 1, o_) for i, o_ in enumerate(gs))
    pages_id = add(b"")                                   # placeholder
    kids = []
    for pg in pages:
        data = zlib.compress(page_stream(pg), 6)
        cid = add(b"<< /Length " + str(len(data)).encode() + b" /Filter /FlateDecode >>\nstream\n" + data +
                  b"\nendstream")
        kids.append(add("<< /Type /Page /Parent {} 0 R /MediaBox [0 0 {} {}] /Contents {} 0 R /Resources << /Font "
                        "<< /F1 {} 0 R /F2 {} 0 R >> /ExtGState << {} >> >> >>".format(
                            pages_id, _f(PAGE_W / PT), _f(PAGE_H / PT), cid, font[0], font[1], gs_res).encode("latin-1")))
    objs[pages_id - 1] = "<< /Type /Pages /Kids [{}] /Count {} >>".format(
        " ".join("{} 0 R".format(k) for k in kids), len(kids)).encode("latin-1")
    cat = add("<< /Type /Catalog /Pages {} 0 R >>".format(pages_id).encode("latin-1"))
    info = add("<< /Title (Bergama context diagrams) /Producer ({}) >>".format(SCRIPT).encode("latin-1"))
    out = bytearray(b"%PDF-1.4\n%\xe2\xe3\xcf\xd3\n")
    offs = []
    for i, b in enumerate(objs):
        offs.append(len(out))
        out += "{} 0 obj\n".format(i + 1).encode() + b + b"\nendobj\n"
    x = len(out)
    out += "xref\n0 {}\n0000000000 65535 f \n".format(len(objs) + 1).encode()
    for o_ in offs:
        out += "{:010d} 00000 n \n".format(o_).encode()
    out += "trailer\n<< /Size {} /Root {} 0 R /Info {} 0 R >>\nstartxref\n{}\n%%EOF\n".format(
        len(objs) + 1, cat, info, x).encode()
    with open(path, "wb") as fh:
        fh.write(bytes(out))


